head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//

/*************************************************************
 * 메뉴 정의 스크립트
 *************************************************************/
/*
 * 화면에서 메뉴 호출
 */
/**
 * @method
 * @name menuLink
 * @description desc
 * @param {string} menuId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuLink = function(menuId) {
    scwin.menuLinkVal(menuId, "", "", "", "");
};


/*
 * 다운로드 메뉴 호출
 */
/**
 * @method
 * @name downMenuLink
 * @description desc
 * @param {string} menuId desc
 * @param {string} curSh desc
 * @param {string} groupId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.downMenuLink = function(menuId, curSh, groupId) {
    scwin.menuLinkVal(menuId, "", "", curSh, groupId);
};


/*
 * 신청권한 확인 후 화면에서 메뉴 호출
 */
/**
 * @method
 * @name menuAuthLink
 * @description desc
 * @param {string} menuId desc
 * @param {string} authYn desc
 * @param {string} usrTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuAuthLink = function(menuId, authYn, usrTpCd) {
    //alert('authYn'+authYn);
    if (usrTpCd == '1' || usrTpCd == '4') {
        scwin.menuLinkVal(menuId, "", "", "", "");
    } else {
        if (authYn == 'Y') {
            scwin.menuLinkVal(menuId, "", "", "", "");
        } else {
            alert('해당법인은 선택상품의 코드신청 권한이 없습니다.\n\r필요시 표준코드담당자(02-3774-8684)에게 연락주시기 바랍니다.');
        }
    }
};




/*
 * els/dls 신청권한 확인 후 화면에서 메뉴 호출
 */
/**
 * @method
 * @name menuAuthElsDlsLink
 * @description desc
 * @param {string} menuId desc
 * @param {string} authElsYn desc
 * @param {string} authElbYn desc
 * @param {string} usrTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuAuthElsDlsLink = function(menuId, authElsYn, authElbYn, usrTpCd) {
    //alert('[authElsYn]:'+authElsYn+'[authElbYn]:'+authElbYn);
    if (authElsYn == 'Y' || authElbYn == 'Y') {
        scwin.menuAuthLink(menuId, 'Y', usrTpCd);
    } else {
        scwin.menuAuthLink(menuId, 'N', usrTpCd);
    }
};



/*
 * 수수료부여여부 확인 후 화면에서 메뉴 호출
 */
/**
 * @method
 * @name menuGrntFeeLink
 * @description desc
 * @param {string} menuId desc
 * @param {string} authGrntYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuGrntFeeLink = function(menuId, authGrntYn) {
    //alert('[authElsYn]:'+authElsYn+'[authElbYn]:'+authElbYn);
    scwin.menuLink(menuId);
    /**
    if(authGrntYn == 'Y'){
    	menuLink(menuId);
    } else {
    	alert('서비스 준비중입니다.');
    }
    */

};



/*
 * 이동시 파라미터 추가
 */
/**
 * @method
 * @name menuLinkVal
 * @description desc
 * @param {string} menuId desc
 * @param {string} isurCd desc
 * @param {string} kind desc
 * @param {string} curSh desc
 * @param {string} groupId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuLinkVal = function(menuId, isurCd, kind, curSh, groupId) {
    var goUrl = "";
    var param = "";
    if (scwin.GetByte(isurCd) > 0) {
        param = "&isur_cd=" + isurCd;
    }
    if (scwin.GetByte(kind) > 0) {
        param = param + "&kind=" + kind;
    }
    if (scwin.GetByte(curSh) > 0) {
        param = param + "&curSh=" + curSh;
    }
    if (scwin.GetByte(groupId) > 0) {
        param = param + "&groupId=" + groupId;
    }

    //메인
    if (menuId == "00000") goUrl = "/index.jsp";
    //표준코드란
    if (menuId == "00001") {
        scwin.main_openWinId('isu_help');
        return;
    }
    //표준코드 신청안내
    if (menuId == "00002") {
        scwin.main_openWinId('isu_req');
        return;
    }
    //표준코드 신청 시뮬레이션
    if (menuId == "00003") {
        scwin.main_openWinId('isu_simul');
        return;
    }
    //개인정보처리방침
    if (menuId == "00004") {
        scwin.main_openWinId('isu_security');
        return;
    }
    //회원가입화면 
    if (menuId == "00006") {
        scwin.main_openWinId('join_member');
        return;
    }

    //발행기관신청
    if (menuId == "05000") {
        scwin.checkRegTimeEnd();
        goUrl = "/corp/corp.do?method=corpNewReq"; //{	popupReqCorp();	return;}

    }
    //기존발행기관 아이디신청
    if (menuId == "05001") {
        scwin.checkRegTimeEnd();
        goUrl = "/corp/register.do?method=searchMemberView";
    }

    //발행기관신청결과 조회
    if (menuId == "05100") goUrl = "/corp/corpList.do?method=corpNewReqList";
    //발행기관정보조회
    if (menuId == "05200") goUrl = "/corp/corpList.do?method=corpInfoList";
    //발행기관변경 신청 결과
    if (menuId == "05300") goUrl = "/corp/corpList.do?method=corpUpdReqList";
    //발행기관변경 신청
    if (menuId == "05400") {
        scwin.checkRegTimeEnd();
        goUrl = "/corp/corp.do?method=corpUpdReq";
    }
    //발행기관 담당자정보변경
    if (menuId == "05500") goUrl = "/account/userInfo.do?method=searchUserInfo";
    //발행기관 담당자비밀번호변경
    if (menuId == "05600") goUrl = "/account/userPw.do?method=updatePasswordForm&deal_div=2";
    //자사발행기관 정보조회
    if (menuId == "05700") goUrl = "/corp/corp.do?method=corpInfoView";
    //자사발행종목 정보조회
    if (menuId == "05800") goUrl = "/corp/corpStdcd.do?method=corpStdcdList";
    //로그인사용자 정보변경
    if (menuId == "05900") goUrl = "/account/userInfo.do?method=searchSysUserInfo";
    //아이디 변경
    if (menuId == "06000") goUrl = "/account/userId.do?method=updateIntegUsrIdForm";

    //표준코드신청 - 주권
    if (menuId == "10000") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/stock.do?method=stockRegForm";
    }
    //표준코드신청 - 채권
    if (menuId == "10100") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/bond.do?method=bondRegForm";
    }
    //표준코드신청 - 수익증권
    if (menuId == "10200") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/bene.do?method=beneRegForm";
    }
    //표준코드신청 - 신주인수권증권
    if (menuId == "10300") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/comwarr.do?method=comwarrRegForm";
    }
    //표준코드신청 - 신주인수권증서
    if (menuId == "10400") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/subwarr.do?method=subwarrRegForm";
    }
    //표준코드신청 - 양도성예금증서(CD)
    if (menuId == "10500") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/cd.do?method=cdRegForm";
    }
    //표준코드신청 - 전자단기사채/CP
    if (menuId == "10600") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/cp.do?method=cpRegForm";
    }
    //표준코드신청 - 유가증권예탁증서(DR)
    if (menuId == "10700") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/dr.do?method=drRegForm";
    }
    //표준코드신청 - 스트립
    if (menuId == "10800") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/stript.do?method=striptRegForm";
    }
    //표준코드신청 - ELS/DLS
    if (menuId == "10900") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/elsdls.do?method=elsdlsRegForm";
    }
    //표준코드신청 - 주식워런트(ELW)
    if (menuId == "11000") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/elw.do?method=elwRegForm";
    }
    //표준코드신청 - 상장지수증권(ETN)
    if (menuId == "11100") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/etn.do?method=etnRegForm";
    }
    //표준코드신청 - 투자계약증권
    if (menuId == "11200") {
        scwin.checkRegTimeEnd();
        goUrl = "/stdcd/invest.do?method=investRegForm";
    }

    //표준코드 신청결과
    if (menuId == "15000") goUrl = "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList" + param;

    //표준코드조회-전체
    if (menuId == "20000") goUrl = "/srch/srch.do?method=srchList";

    //다운로드 - 국세청/한국은행
    //다운로드 - 발행기관
    if (menuId == "25000") goUrl = "/down/downList.do?method=downList&type=25000" + param;
    //다운로드 - 주권
    if (menuId == "25100") goUrl = "/down/downList.do?method=downList&type=25100" + param;
    //다운로드 - 채권
    if (menuId == "25200") goUrl = "/down/downList.do?method=downList&type=25200" + param;
    //다운로드 - 수익증권
    if (menuId == "25300") goUrl = "/down/downList.do?method=downList&type=25300" + param;
    //다운로드 - 신주인수권
    if (menuId == "25400") goUrl = "/down/downList.do?method=downList&type=25400" + param;
    //다운로드 - 양도성예금증서(CD)
    if (menuId == "25500") goUrl = "/down/downList.do?method=downList&type=25500" + param;
    //다운로드 - 전자단기사채/CP
    if (menuId == "25600") goUrl = "/down/downList.do?method=downList&type=25600" + param;
    //다운로드 - 유가증권예탁증서(DR)
    if (menuId == "25700") goUrl = "/down/downList.do?method=downList&type=25700" + param;
    //다운로드 - 스트립
    if (menuId == "25800") goUrl = "/down/downList.do?method=downList&type=25800" + param;
    //다운로드 - ELS/DLS
    if (menuId == "25900") goUrl = "/down/downList.do?method=downList&type=25900" + param;
    //다운로드 - 주식워런트(ELW)
    if (menuId == "26000") goUrl = "/down/downList.do?method=downList&type=26000" + param;
    //다운로드 - 선물/옵션 
    if (menuId == "26100") goUrl = "/down/downList.do?method=downList&type=26100" + param;
    //다운로드 - 지표
    if (menuId == "26200") goUrl = "/down/downList.do?method=downList&type=26200" + param;
    //다운로드 - 일반상품
    if (menuId == "26300") goUrl = "/down/downList.do?method=downList&type=26300" + param;
    //다운로드 - ETN
    if (menuId == "26400") goUrl = "/down/downList.do?method=downList&type=26400" + param;
    //다운로드 - 투자계약증권
    if (menuId == "26500") goUrl = "/down/downList.do?method=downList&type=26500" + param;

    //다운로드 - 기타기관/예탁원(모든상품)
    if (menuId == "40000") goUrl = "/srch/srch.do?method=ksdDownList" + param;

    //공지사항
    if (menuId == "30000") goUrl = "/info/notice.do?method=noticeList";
    //FAQ
    if (menuId == "30001") goUrl = "/info/faq.do?method=faqList";
    //표준코드란
    if (menuId == "30002") goUrl = "/info/code.do?method=codeMeaning";
    //표준코드 체계
    if (menuId == "30003") goUrl = "/info/code.do?method=codeSystem";
    //표준코드 관리기준
    if (menuId == "30004") goUrl = "/info/code.do?method=codeRule";
    //표준코드 신청안내
    if (menuId == "30005") goUrl = "/info/code.do?method=codeInfo";
    //업무서식 다운로드
    if (menuId == "30006") goUrl = "/info/bizform.do?method=bizformList";

    //영문 메인
    if (menuId == "35000") goUrl = "/main/eng.do?method=eng_main";
    //영문 표준코드란
    if (menuId == "35001") {
        scwin.main_openWinId('eng_isu_help');
        return;
    }
    //영문 표준코드 신청안내
    if (menuId == "35002") {
        scwin.main_openWinId('eng_isu_req');
        return;
    }
    //영문 발행기관 조회
    if (menuId == "35100") goUrl = "/main/eng.do?method=eng_isurSrch";

    //수수료 안내
    if (menuId == "50000") goUrl = "/fee/fee.do?method=feeInfo";
    //부여수수료 납부현황
    if (menuId == "50100") goUrl = "/fee/fee.do?method=feeList";
    //수수료안내 공문신청 화면
    if (menuId == "50200") goUrl = "/fee/fee.do?method=feePayOfcdocReqView";

    //개발 후 삭제 예정
    if (menuId == "" || goUrl == "") alert("개발중인 화면입니다.");

    //alert(goUrl);

    //이동주소가 있을 경우만 이동
    if (goUrl != "") {
        location.href = goUrl;
    }
};





/*
 * 반송건 재신청용 메뉴
 * 상품 / 접수번호 / 가상계좌
 */
/**
 * @method
 * @name returnMenuLink
 * @description desc
 * @param {string} menuId desc
 * @param {string} applId desc
 * @param {string} acntNo desc
 * @param {string} feeProcsStatCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.returnMenuLink = function(menuId, applId, acntNo, feeProcsStatCd) {
    var goUrl = "";
    var param = "&applId=" + applId + "&acntNo=" + acntNo + "&feeProcsStatCd=" + feeProcsStatCd;
    scwin.checkRegTimeEnd();

    //표준코드신청 - 주권
    if (menuId == "10000") goUrl = "/stdcd/stock.do?method=stockRegForm";
    //표준코드신청 - 채권
    if (menuId == "10100") goUrl = "/stdcd/bond.do?method=bondRegForm";
    //표준코드신청 - 수익증권
    if (menuId == "10200") goUrl = "/stdcd/bene.do?method=beneRegForm";
    //표준코드신청 - 신주인수권증권
    if (menuId == "10300") goUrl = "/stdcd/comwarr.do?method=comwarrRegForm";
    //표준코드신청 - 신주인수권증서
    if (menuId == "10400") goUrl = "/stdcd/subwarr.do?method=subwarrRegForm";
    //표준코드신청 - 양도성예금증서(CD)
    if (menuId == "10500") goUrl = "/stdcd/cd.do?method=cdRegForm";
    //표준코드신청 - 전자단기사채/CP
    if (menuId == "10600") goUrl = "/stdcd/cp.do?method=cpRegForm";
    //표준코드신청 - 유가증권예탁증서(DR)
    if (menuId == "10700") goUrl = "/stdcd/dr.do?method=drRegForm";
    //표준코드신청 - 스트립
    if (menuId == "10800") goUrl = "/stdcd/stript.do?method=striptRegForm";
    //표준코드신청 - ELS/DLS
    if (menuId == "10900") goUrl = "/stdcd/elsdls.do?method=elsdlsRegForm";
    //표준코드신청 - 주식워런트(ELW)
    if (menuId == "11000") goUrl = "/stdcd/elw.do?method=elwRegForm";
    //표준코드신청 - 상장지수증권(ETN)
    if (menuId == "11100") goUrl = "/stdcd/etn.do?method=etnRegForm";
    //표준코드신청 - 투자계약증권
    if (menuId == "11200") goUrl = "/stdcd/invest.do?method=investRegForm";

    //개발 후 삭제 예정
    if (menuId == "" || goUrl == "") alert("개발중인 화면입니다.");

    //이동주소가 있을 경우만 이동
    if (goUrl != "") {
        location.href = goUrl + param;
    }
};




/*************************************************************
 * 팝업 정의 스크립트
 *************************************************************/
/*
 * 신청시간 종료 시간 체크
 */
/**
 * @method
 * @name checkRegTimeEnd
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkRegTimeEnd = function() {
    var now = new Date();
    var regEndDt = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 17, 00, 00);
    if (now > regEndDt) {
        win = window.open("/stdcd/stdcd.do?method=regTimeEnd", "신청시간종료안내", "toolbar=no, location=no, status=no, menubar=no, scrollbars=no, resizable=yes,width=700, height=370");
    }
};



/*
 * 윈도우 닫기
 */
/**
 * @method
 * @name closeWin
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.closeWin = function() {
    if (confirm("모든 작업을 취소하시겠습니까?")) {
        this.close();
    }
};



/*
 * 메인화면- 팝업화면 처리
 */
/**
 * @method
 * @name main_openWinId
 * @description desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.main_openWinId = function(id) {
    //표준코드란 팝업화면 
    if (id == "isu_help") {
        win = window.open("/main/main.do?method=mainContent1", "표준코드란", "toolbar=no, location=no, status=no, menubar=no, scrollbars=yes, resizable=yes,width=600, height=580");
    }
    //표준코드 신청안내 팝업화면
    if (id == "isu_req") {
        win = window.open("/main/main.do?method=mainContent2", "표준코드신청안내", "toolbar=no, location=no, status=no, menubar=no, scrollbars=no, resizable=yes,width=800,height=650");
    }
    //표준코드 신청 시뮬레이션
    if (id == "isu_simul") {
        win = window.open("/main/main.do?method=mainContent3", "표준코드신청시뮬레이션", "toolbar=no, location=no, status=no, menubar=no, scrollbars=no, resizable=yes,width=1020,height=900");
    }
    //표준코드 신청 개인정보처리방침
    if (id == "isu_security") {
        win = window.open("/main/main.do?method=mainContent4", "표준코드신청개인정보처리방침", "toolbar=no, location=no, status=no, menubar=no, scrollbars=yes, resizable=yes,width=800,height=650");
    }
    //영문 표준코드란 팝업화면 
    if (id == "eng_isu_help") {
        win = window.open("/main/eng.do?method=eng_content1", "isin1", "toolbar=no, location=no, status=no, menubar=no, scrollbars=no, resizable=yes,width=600, height=580");
    }
