/*
 * 검색기간을 당일로 셋팅
 */
/**
 * @method
 * @name fn_setToday
 * @description desc
 * @param {string} start_dd desc
 * @param {string} end_dd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setToday = function(start_dd, end_dd) {
    if ($("#" + end_dd).val() == '') {
        var now = new Date();
        var year = now.getFullYear();
        var mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        var day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();
        $("#" + end_dd).val(year + mon + day);
        $("#" + start_dd).val(year + mon + day);
    }
    var toD = $("#" + end_dd).val();
    var n = parseInt(toD.substr(4, 2), 10) - 1;
    var st = new Date(toD.substr(0, 4), n, toD.substr(6, 2));
    $("#" + start_dd).val($("#" + end_dd).val());
};


/*
 * 1,3,6개월 날짜 처리
 */
/**
 * @method
 * @name fn_appDate1
 * @description desc
 * @param {string} start_dd desc
 * @param {string} end_dd desc
 * @param {string} m desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_appDate1 = function(start_dd, end_dd, m) {
    if ($("#" + end_dd).val() == '') {
        var now = new Date();
        var year = now.getFullYear();
        var mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        var day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();

        //var mon = fnLeg(now.getMonth()+1);
        //var day = fnLeg(now.getDate());
        $("#" + end_dd).val(year + mon + day);
    }
    var toD = $("#" + end_dd).val();
    var n = parseInt(toD.substr(4, 2), 10) - 1;
    var st = new Date(toD.substr(0, 4), n, toD.substr(6, 2));
    if (m == 1) {
        var apDate = new Date(st - 30 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "" + scwin.fnLeg(apDate.getMonth() + 1) + "" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 3) {
        var apDate = new Date(st - 90 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "" + scwin.fnLeg(apDate.getMonth() + 1) + "" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 6) {
        var apDate = new Date(st - 181 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "" + scwin.fnLeg(apDate.getMonth() + 1) + "" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 12) {
        var apDate = new Date(st - 365 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "" + scwin.fnLeg(apDate.getMonth() + 1) + "" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 36) {
        var apDate = new Date(st - 1095 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "" + scwin.fnLeg(apDate.getMonth() + 1) + "" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else {
        alert("잘못된 날짜값입니다.");
        $("#" + end_dd).focus();
        return;
    }
};



/*
 * 1,3,6개월 날짜 처리
 */
/**
 * @method
 * @name fn_appDate2
 * @description desc
 * @param {string} start_dd desc
 * @param {string} end_dd desc
 * @param {string} m desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_appDate2 = function(start_dd, end_dd, m) {
    if ($("#" + end_dd).val() == '') {
        var now = new Date();
        var year = now.getFullYear();
        var mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        var day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();

        //var mon = fnLeg(now.getMonth()+1);
        //var day = fnLeg(now.getDate());
        $("#" + end_dd).val(year + "-" + mon + "-" + day);
    }
    var toD = $("#" + end_dd).val();
    var n = parseInt(toD.substr(5, 2), 10) - 1;
    var st = new Date(toD.substr(0, 4), n, toD.substr(8, 2));
    if (m == 1) {
        var apDate = new Date(st - 30 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "-" + scwin.fnLeg(apDate.getMonth() + 1) + "-" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 3) {
        var apDate = new Date(st - 90 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "-" + scwin.fnLeg(apDate.getMonth() + 1) + "-" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 6) {
        var apDate = new Date(st - 181 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "-" + scwin.fnLeg(apDate.getMonth() + 1) + "-" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 12) {
        var apDate = new Date(st - 365 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "-" + scwin.fnLeg(apDate.getMonth() + 1) + "-" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else if (m == 36) {
        var apDate = new Date(st - 1095 * 1000 * 60 * 60 * 24);
        var toDate = apDate.getFullYear() + "-" + scwin.fnLeg(apDate.getMonth() + 1) + "-" + scwin.fnLeg(apDate.getDate());
        $("#" + start_dd).val(toDate);
    } else {
        alert("잘못된 날짜값입니다.");
        $("#" + end_dd).focus();
        return;
