 * 체크 스크립트
 *************************************************************/
/*
 * 입력 달력 날짜를 Check
 */
/**
 * @method
 * @name Chk_Date
 * @description desc
 * @param {string} Name desc
 * @param {string} Date_Str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Date = function(Name, Date_Str) {
    //숫자인지 체크
    var DON = "";
    var tmp = Name.getValue();
    for (i = 0; i <= tmp.length; i++) {
        if (tmp.substring(i, i + 1) != ",") DON = DON + tmp.substring(i, i + 1);
    }
    if (!scwin.Chk_Digit(DON)) {
        alert(" 숫자만 입력 가능합니다.");
        Name.setValue('');
        Name.focus();
        return false;
    }
    var sdate = Name.getValue();
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(5, 2);
    pday = sdate.substr(8, 2);

    //차후 날짜가 2013-01-01 일 경우
    var tmpdate = sdate.split("-");
    if (tmpdate.length > 2) {
        if (tmpdate.length > 0) pyear = tmpdate[0];
        if (tmpdate.length > 1) pmonth = tmpdate[1];
        if (tmpdate.length > 2) pday = tmpdate[2];
    }
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate != "" && (syear != soyear || smonth != somonth || sday != soday)) {
        alert("입력한 " + Date_Str + "이(가) 올바르지 않습니다 \n\r");
        Name.focus();
        return false;
    }
    if (sdate != "" && sdate.length != 10) {
        alert("입력한 '" + Date_Str + "' 이(가) 10자리가 아닙니다. \n\r");
        Name.focus();
        return false;
    }
    return true;
};


