 * 체크 스크립트
 *************************************************************/
/*
 * 입력 달력 날짜를 Check
 */
/**
 * @method
 * @name Chk_Date2
 * @description desc
 * @param {string} Name desc
 * @param {string} Date_Str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Date2 = function(Name, Date_Str) {
    var sdate = Name.getValue();
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(5, 2);
    pday = sdate.substr(8, 2);
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (syear != '9999') {
        if (sdate != "" && (syear != soyear || smonth != somonth || sday != soday)) {
            alert("입력한 " + Date_Str + "이(가) 올바르지 않습니다 \n\r");
            setTimeout(function() {
                Name.focus();
            }, 10);
            return false;
        }
    }
    if (sdate != "" && sdate.length != 10) {
        alert("입력한 '" + Date_Str + "' 이(가) 10자리가 아닙니다. \n\r");
        setTimeout(function() {
            Name.focus();
        }, 10);
        return false;
    }
    return true;
};



/*
 *  숫자와 '-' 만 포함되어있는지 Check..   아니면 false
 */
/**
 * @method
 * @name Chk_DateForm
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_DateForm = function(str) {
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if ((ch < "0" || ch > "9") && ch != "-" && ch != ",") {
            return false;
        }
    }
    return true;
};


/*
 * 입력값이 'Y', 'N' 이어야 함.. 소문자는 대문자로 바꿈
 */
/**
 * @method
 * @name Chk_YN
 * @description desc
 * @param {string} Name desc
 * @param {string} text desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_YN = function(Name, text) {
    switch (Name.getValue()) {
        case 'Y':
        case 'y':
            Name.setValue('Y');
            break;
        case 'N':
        case 'n':
            Name.setValue('N');
            break;
        case '':
            Name.setValue('');
            break;
        default:
            alert("'" + text + "' 입력값은 'Y' 또는 'N' 이어야 합니다.");
            return false;
    }
    return true;
};


