/* 입력받는 정수형, 소숫점 포함의 값을 체크한다.
   Length1 : 정수형 값의 길이 제한 길이를 지정, 
   Lenght2 : 소숫점 값의 길이 제한 길이를 지정 */
/**
 * @method
 * @name DemicalCheck
 * @description desc
 * @param {string} obj desc
 * @param {string} Lenght1 desc
 * @param {string} Lenght2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.DemicalCheck = function(obj, Lenght1, Lenght2) {
    try {
        // , 를 제거한 금액.
        var val = scwin.Del_MoneyComma_Value(obj.getValue());
        if (val.lastIndexOf('.') != -1) // 찾는 문자 '.' 있다면 해당하는 인덱스의 번호를 반환하지만 없으면 -1을 반환하므로 있으면 실행된다.

        {
            ObjValue = val.split("."); // 입력 받은 값을 ObjValue에 "." 나누어서 저장시킨다.
            //소숫점 두개이상 체크
            if (ObjValue.length <= 2) {
                if (ObjValue[0].length > Lenght1) // 입력받은 정수형의 입력 길이가 6이라면

                {
                    alert("앞자릿수는 " + Lenght1 + "자리까지 입력할 수 있습니다.");
                    setTimeout(function() {
                        obj.focus();
                    }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

                }
                if (ObjValue[1].length > Lenght2) {
                    alert("소숫점 자릿수는 " + Lenght2 + "자리까지 입력할 수 있습니다.");
                    setTimeout(function() {
                        obj.focus();
                    }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

                }
            } else {
                alert("소숫점은 한개만 입력가능합니다.");
                setTimeout(function() {
                    obj.focus();
                }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

            }
        } else

        // 소숫점 입력이 아닌 정수형의 일반적인 입력일 경우

        {
            if (val.length > Lenght1) {
                alert("앞자릿수는 " + Lenght1 + "자리까지 입력할 수 있습니다.");
                setTimeout(function() {
                    obj.focus();
                }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

            }
        }
    } catch (err) {
        alert(err);
    }
};



/* 입력받는 정수형, 소숫점 포함의 값을 체크한다.
   Length1 : 정수형 값의 길이 제한 길이를 지정, 
   Lenght2 : 소숫점 값의 길이 제한 길이를 지정 */
/**
 * @method
 * @name DemicalCheckVal
 * @description desc
 * @param {string} obj desc
 * @param {string} Lenght1 desc
 * @param {string} Lenght2 desc
 * @param {string} nMaxVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.DemicalCheckVal = function(obj, Lenght1, Lenght2, nMaxVal) {
    try {
        if (obj.getValue().lastIndexOf('.') != -1) // 찾는 문자 '.' 있다면 해당하는 인덱스의 번호를 반환하지만 없으면 -1을 반환하므로 있으면 실행된다.

        {
            ObjValue = obj.getValue().split("."); // 입력 받은 값을 ObjValue에 "." 나누어서 저장시킨다.
            //소숫점 두개이상 체크
            if (ObjValue.length <= 2) {
                if (ObjValue[0].length > Lenght1) // 입력받은 정수형의 입력 길이가 6이라면

                {
                    alert("앞자릿수는 " + Lenght1 + "자리까지 입력할 수 있습니다.");
                    setTimeout(function() {
                        obj.focus();
                    }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

                }
                if (ObjValue[1].length > Lenght2) {
                    alert("소숫점 자릿수는 " + Lenght2 + "자리까지 입력할 수 있습니다.");
                    setTimeout(function() {
                        obj.focus();
                    }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

                }
            } else {
                alert("소숫점은 한개만 입력가능합니다.");
                setTimeout(function() {
                    obj.focus();
                }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

            }
        } else

        // 소숫점 입력이 아닌 정수형의 일반적인 입력일 경우

        {
            if (obj.getValue().length > Lenght1) {
                alert("앞자릿수는 " + Lenght1 + "자리까지 입력할 수 있습니다.");
                setTimeout(function() {
                    obj.focus();
                }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

            }
        }

        // max 체크
        if (obj.getValue() > nMaxVal) {
            alert(nMaxVal + " 보다 작은값을 입력하세요.");
            setTimeout(function() {
                obj.focus();
            }, 10); //setTimeout을 사용하여 onblur 보다 focus를 약간 지연동작시킨다.

        }
    } catch (err) {
        alert(err);
    }
};



