 *************************************************************/
/*
 *  금액 입력시 금액에 3자리마다 컴마 찍기 & 우측 정렬
 */
/**
 * @method
 * @name Add_MoneyComma
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_MoneyComma = function(Name) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    var tmp;
    var DON = "";
    tmp = Name.getValue();
    for (i = 0; i <= tmp.length; i++) {
        if (tmp.substring(i, i + 1) != ",") DON = DON + tmp.substring(i, i + 1);
    }
    if (!scwin.Chk_Digit(DON)) {
        alert(" 숫자만 입력 가능합니다.");
        Name.setValue('');
        Name.focus();
        return false;
    }
    factor = DON.length % 3;
    su = (DON.length - factor) / 3;
    src = DON.substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        } else {
            src += ",";
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        }
    }
    if (src.substring(0, 2) == '-,') {
        Name.setValue(src.substring(0, 1) + src.substring(2));
    } else {
        Name.setValue(src);
    }
    return true;
};


