/*
 *  금액 입력시 금액에 3자리마다 컴마 찍기 & 우측 정렬
 */
/**
 * @method
 * @name Add_Comma
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_Comma = function(obj) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    var tmp;
    var tmp1 = "";
    var DON = "";
    var ObjValue;
    var isExistDot = false;
    tmp = obj.getValue();
    if (tmp == "") {
        return;
    }

    // . 이 있는지 확인
    if (tmp.indexOf(".") >= 0) {
        isExistDot = true;
    }
    if (isExistDot) {
        ObjValue = tmp.split("."); // 입력 받은 값을 ObjValue에 "." 나누어서 저장시킨다.
        tmp = ObjValue[0];
        tmp1 = ObjValue[1];
        if (tmp1 == undefined || tmp1 == "") {
            tmp1 = ".";
        } else {
            tmp1 = "." + tmp1;
        }
    }

    // .xxxx 이렇게 입력한 경우
    if (tmp == "") {
        obj.setValue(tmp1);
        return;
    }
    DON = scwin.Del_MoneyComma_Value(tmp);
    factor = DON.length % 3;
    su = (DON.length - factor) / 3;
    src = DON.substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        } else {
            src += ",";
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        }
    }
    if (src.substring(0, 2) == '-,') {
        obj.setValue(src.substring(0, 1) + src.substring(2) + tmp1);
    } else {
        obj.setValue(src + tmp1);
    }
    return true;
};



/* 
 * 금액 값을 금액에 3자리마다 컴마 찍기 & 우측 정렬
 * 값 리턴
 */
/**
 * @method
 * @name get_addMoneyComma
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.get_addMoneyComma = function(str) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    var tmp;
    var DON = "";
    tmp = str;
    for (i = 0; i <= tmp.length; i++) {
        if (tmp.substring(i, i + 1) != ",") DON = DON + tmp.substring(i, i + 1);
    }
    if (!scwin.Chk_Digit(DON)) {
        alert(" 숫자만 입력 가능합니다.");
        str = '';
        return;
    }
    factor = DON.length % 3;
    su = (DON.length - factor) / 3;
    src = DON.substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        } else {
            src += ",";
            src += DON.substring(factor + (3 * i), factor + 3 + (3 * i));
        }
    }
    if (src.substring(0, 2) == '-,') {
        str = src.substring(0, 1) + src.substring(2);
    } else {
        str = src;
    }
    return str;
};


