/*
 *  문자열의 값을 바이트수로 변환하여 리턴
 */
/**
 * @method
 * @name GetByte
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.GetByte = function(val) {
    var str = $c.ut.trim();
    var i, ch, bytes;
    //    var    app, isNe=0;

    if (str == '') return 0;
    //        app = navigator.appName;
    //    if(app == 'Netscape') isNe = 1;

    for (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        i = 0, bytes = 0; i < str.length; i++) {
        ch = str.charAt(i);
        if (scwin.IsInt(ch)) bytes++;

        else if (scwin.IsLower(ch)) bytes++;

        else if (scwin.IsUpper(ch)) bytes++;

        else if (scwin.IsEtc(ch)) bytes++;

        else if (scwin.IsEnter(ch)) bytes;

        else {
            bytes += 2;
            //        if(isNe)
            //            i++;

        }
    }
    return bytes;
};



