/*
 * 숫자나 영문 대문자만 입력
 */
/**
 * @method
 * @name checkNumUpperEnglish
 * @description desc
 * @param {string} aObj desc
 * @param {string} aDesc desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkNumUpperEnglish = function(aObj, aDesc) {
    var val = aObj.getValue();
    var len = val.length;
    for (var i = 0; i < len; i++) {
        var ch = val.charAt(i);
        var isNumEnglish = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z');
        if (!isNumEnglish) {
            aObj.select();
            alert(aDesc + " - " + "숫자나 영문 대문자만 입력하십시오.");
            return false;
        }
    }
    return true;
};



