/*
 * E-mail 주소 체크 함수
 */
/**
 * @method
 * @name CheckEmail
 * @description desc
 * @param {string} email_addr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CheckEmail = function(email_addr) {
    if (email_addr == "") return false;
    var t = email_addr;
    var Alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var Digit = '1234567890';
    var Symbol = '_-';
    var check = '@.' + Alpha + Digit + Symbol;
    for (i = 0; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) < 0) {
            return false;
        } var check = '@';
    var a = 0;
    for (i = 0; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) >= 0) a = i;
    var check = '.';
    var b = 0;
    for (i = a + 1; i < t.length; i++)
        if (check.indexOf(t.substring(i, i + 1)) >= 0) b = i;
    if (a != 0 && b != 0 && b != t.length - 1) {
        return true;
    } else {
        return false;
    }
};



/*
 * password check(object)
 */
/**
 * @method
 * @name checkPwd
 * @description desc
 * @param {string} aObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkPwd = function(aObj) {
    var val = aObj.getValue();
    if (scwin.checkPwdStr(val)) {
        return true;
    }
    return false;
};


/*
 * password check(string)
 */
/**
 * @method
 * @name checkPwdStr
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkPwdStr = function(val) {
    var pwVal = val;

    // 길이 9자  이상 체크 
    if (pwVal.length < 9) {
        alert("비밀번호를 9자 이상 입력하십시요");
        return false;
    }

    // 워드문자(숫자,영문자,_) 또는 허용특수기호로 구성  체크
    var strChk = /^[\a-z0-9_!@#$^&*()]{9,}$/;
    if (!(strChk.test(pwVal))) {
        alert("비밀번호는 영문대문자,한글,띄어쓰기는 안됩니다.\n_!@#$^&*() 이외의 특수문자는 안됩니다.");
        return false;
    }


    // 사용자 계정과 동일한 비밀번호 체크

    // 동일한 문자 또는 숫자가 3자 이상 사용된 비밀번호, 주기성 문자(abcd, 1234 등)
    var sameCount = 1; // 동일문자 연속 횟수
    var isCont = true; // 주기성 문자 여부

    for (var i = 0; i < pwVal.length - 1; i++) {
        var currentChar = pwVal.charAt(i);
        var nextChar = pwVal.charAt(i + 1);
        var currentCharNum = parseInt(currentChar.charCodeAt(0));
        var continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar == nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) break;
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum == continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        alert('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    if (isCont) {
        alert('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }

    // 문자 또는 숫자만으로 구성된 비밀번호 체크
    var charChk = /^[\a-z]{9,}$/;
    var numChk = /^[\d]{9,}$/;

    // 문자로만 구성 또는 숫자로만 구성 체크
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        alert('문자 또는 숫자만으로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }

    // 키보드상의 연속된 배열(asdf, qwerty 등)로 구성된 비밀번호 체크
    var keyboardWord = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
    for (var i = 0; i < keyboardWord.length; i++) {
        if (!(keyboardWord[i].indexOf(pwVal.toLowerCase()) < 0)) {
            alert('키보드상의 연속된 배열(asdf, qwerty 등)로 구성된 비밀번호는 사용하실 수 없습니다.');
            return false;
        }
    }

    // 특수문자 필수 체크
    var specialStr = /[_!@#$^&*()]/gi;
    if (!specialStr.test(pwVal)) {
        alert("특수문자를 꼭 입력하십시요");
        return false;
    }

    // 모든 테스트 pass
    return true;
};



