/*
 * password check(string, string)
 */
/**
 * @method
 * @name checkPwdStr2
 * @description desc
 * @param {string} val desc
 * @param {string} telId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkPwdStr2 = function(val, telId) {
    var pwVal = val;
    var telNo = $("#" + telId).val();

    // 길이 9자  이상 체크 
    if (pwVal.length < 9) {
        alert("비밀번호를 9자 이상 입력하십시요");
        return false;
    }

    // 워드문자(숫자,영문자,_) 또는 허용특수기호로 구성  체크
    var strChk = /^[\a-z0-9_!@#$^&*()]{9,}$/;
    if (!(strChk.test(pwVal))) {
        alert("비밀번호는 영문대문자,한글,띄어쓰기는 안됩니다.\n_!@#$^&*() 이외의 특수문자는 안됩니다.");
        return false;
    }

    // 전화번호와 비밀번호 체크
    if (pwVal.indexOf(telNo) > -1) {
        alert('전화번호가 포함된 비밀번호는 사용할 수 없습니다.');
        return false;
    }

    // 동일한 문자 또는 숫자가 3자 이상 사용된 비밀번호, 주기성 문자(abcd, 1234 등)
    var sameCount = 1; // 동일문자 연속 횟수
    var isCont = true; // 주기성 문자 여부

    for (var i = 0; i < pwVal.length - 1; i++) {
        var currentChar = pwVal.charAt(i);
        var nextChar = pwVal.charAt(i + 1);
        var currentCharNum = parseInt(currentChar.charCodeAt(0));
        var continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar == nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) break;
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum == continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        alert('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    if (isCont) {
        alert('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }

    // 문자 또는 숫자만으로 구성된 비밀번호 체크
    var charChk = /^[\a-z]{9,}$/;
    var numChk = /^[\d]{9,}$/;

    // 문자로만 구성 또는 숫자로만 구성 체크
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        alert('문자 또는 숫자만으로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }

    // 키보드상의 연속된 배열(asdf, qwerty 등)로 구성된 비밀번호 체크
    var keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (var i = 0; i < keyboardWord.length; i++) {
        for (var j = 0; j < keyboardWord[i].length; j++) {
            //alert(keyboardWord[i].substring(j,j+4));
            if (keyboardWord[i].substring(j, j + 4).length == 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    return false;
                }
            }
        }
    }

    // 특수문자 필수 체크
    var specialStr = /[_!@#$^&*()]/gi;
    if (!specialStr.test(pwVal)) {
        alert("특수문자를 꼭 입력하십시요");
        return false;
    }

    // 모든 테스트 pass
    return true;
};



/*
 * 공지사항 FAQ 검색어 특수문자체크
 */
/**
 * @method
 * @name fn_boardCheck
 * @description desc
 * @param {string} word desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_boardCheck = function(word) {
    var str = word.getValue();
    // 특수문자 필수 체크
    var specialStr = /[%]/gi;
    if (specialStr.test(str) || str == "%") {
        alert("검색어에 다음 문자를 사용할 수 없습니다.\n\n           %");
        word.setValue("");
        word.focus();
        return false;
    }
    return true;
};


