 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_emailCheck = function() {
    var code = event.keyCode;
    if ((code >= 37 && code <= 40) || (code >= 65 && code <= 90) || (code >= 48 && code <= 57) || (code >= 96 && code <= 105) || code == 8 || code == 9 || code == 46 || code == 110 || code == 190 || code == 16 || code == 189) event.returnValue = true;

    else event.returnValue = false;
};



