/* 입력받는 정수형, 소숫점 포함의 값을 체크한다. // '-', '.' 체크
Length1 : 정수형 값의 길이 제한 길이를 지정, 
Lenght2 : 소숫점 값의 길이 제한 길이를 지정 */
/**
 * @method
 * @name DemicalCheck_minus
 * @description desc
 * @param {string} obj desc
 * @param {string} Lenght1 desc
 * @param {string} Lenght2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.DemicalCheck_minus = function(obj, Lenght1, Lenght2) {
    try {
        if (obj.getValue().lastIndexOf('-') != -1) // 찾는 문자 '-' 있다면 해당하는 인덱스의 번호를 반환하지만 없으면 -1을 반환하므로 있으면 실행된다.

        {
            ObjValueMinus = obj.getValue().split("-"); // 입력 받은 값을 ObjValue에 "-" 나누어서 저장시킨다.

            //마이너스 두개이상 체크
            if (ObjValueMinus.length <= 2) {
                if (ObjValueMinus[0].length != 0) {
                    alert("마이너스가 잘못된 형식으로 입력되었습니다. 다시 입력해 주세요.");
                    obj.setValue("");
                    obj.focus();
                }
                if (ObjValueMinus[1].length == 0) {
                    alert("마이너스가 잘못된 형식으로 입력되었습니다. 다시 입력해 주세요.");
                    obj.setValue("");
                    obj.focus();
                }
            } else {
                alert("마이너스는 한개만 입력가능합니다. 다시 입력해 주세요.");
                obj.setValue("");
                obj.focus();
            }
        }
        if (obj.getValue().lastIndexOf('.') != -1) // 찾는 문자 '.' 있다면 해당하는 인덱스의 번호를 반환하지만 없으면 -1을 반환하므로 있으면 실행된다.

        {
            ObjValue = obj.getValue().split("."); // 입력 받은 값을 ObjValue에 "." 나누어서 저장시킨다.
            //소숫점 두개이상 체크
            if (ObjValue.length <= 2) {
                if (ObjValue[0].length > Lenght1) // 입력받은 정수형의 입력 길이가 6이라면

                {
                    alert("정수 자리는 " + Lenght1 + "자리 이상일 수 없습니다. 다시 입력해 주세요.");
                    obj.setValue("");
                    obj.focus();
                }
                if (ObjValue[1].length > Lenght2) {
                    alert("소숫점 자리는 " + Lenght2 + "자리 이상일 수 없습니다. 다시 입력해 주세요.");
                    obj.setValue("");
                    obj.focus();
                }
                if (ObjValue[0].length == 0 || ObjValue[1].length == 0) {
                    alert("정수 혹은 소숫점 자리가 입력되지 않았습니다. 다시 입력해 주세요.");
                    obj.setValue("");
                    obj.focus();
                }
            } else {
                alert("소숫점은 한개만 입력가능합니다. 다시 입력해 주세요.");
                obj.setValue("");
                obj.focus();
            }
        } else

        // 소숫점 입력이 아닌 정수형의 일반적인 입력일 경우

        {
            if (obj.getValue().length > Lenght1) {
                alert("정수자리는 " + Lenght1 + "자리 이상일 수 없습니다. 다시 입력해 주세요.");
                obj.setValue("");
                obj.focus();
            }
        }
    } catch (err) {
        alert(err);
        obj.setValue("");
    }
};



