/*
 * 입력시 숫자와 '.' 만 입력 object
 */
/**
 * @method
 * @name fn_numPointChkObj
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_numPointChkObj = function(obj) {
    var keyVal = window.event.keyCode;
    if (keyVal == 13) return;
    if ((keyVal > 47 && keyVal < 58) || keyVal == 8 || keyVal == 9 || keyVal == 16 || keyVal == 46 || keyVal == 60 || keyVal == 144) {
        if ((keyVal > 47 && keyVal < 58) || (keyVal > 95 && keyVal < 106) || keyVal == 60) {
            if (window.event.shiftKey) event.returnValue = false;

            else event.returnValue = true;
        }
    } else {
        alert("숫자로만 입력하세요.");
        obj.setValue("");
        obj.focus();
        event.returnValue = false;
    }
};
/**
 * @method
 * @name num2won
 * @description desc
 * @param {string} chknum desc
 * @param {string} spanid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.num2won = function(chknum, spanid) {
    val = chknum.getValue();
    var won = new Array();
    re = /^[1-9][0-9]*$/;
    num = val.toString().split(',').join('');
    if (!re.test(num)) {
        chknum.setValue('');
        eval(spanid).innerHTML = '';
        //hanview.innerHTML = '';

    } else {
        var price_unit0 = new Array('', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구');
        var price_unit1 = new Array('', '십', '백', '천');
        var price_unit2 = new Array('', '만', '억', '조', '경', '해', '시', '양', '구', '간', '정');
        for (i = num.length - 1; i >= 0; i--) {
            won[i] = price_unit0[num.substr(num.length - 1 - i, 1)];
            if (i > 0 && won[i] != '') won[i] += price_unit1[i % 4];
            if (i % 4 == 0) won[i] += price_unit2[(i / 4)];
        }
        for (i = num.length - 1; i >= 0; i--) {
            if (won[i].length == 2) won[i - i % 4] += '-';
            if (won[i].length == 1 && i > 0) won[i] = '';
            if (i % 4 != 0) won[i] = won[i].replace('일', '');
        }
        won = won.reverse().join('').replace(/-+/g, '');
        //hanview.innerHTML = '['+won+']';
        eval(spanid).innerHTML = '[' + won + ']';
    }
};



/*
 * 숫자를 한글 읽기로 표현
 */
/**
 * @method
 * @name fn_int2han
 * @description desc
 * @param {string} val desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_int2han = function(val, id) {
    var han_unit_1 = new Array('', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구'); //숫자
    var han_unit_2 = new Array('', '십', '백', '천');
    var han_unit_3 = new Array('', '만', '억', '조', '경', '해', '자', '양', '구', '간', '정', '재', '극', '항하사', '아승기', '나유타', '불가사의', '무량대수');
    var result = "";
    var temp = "";
    var int_unit = "";
    var i, j, k;

    //컴마제거
    val = scwin.Del_MoneyComma_Value(val);
    if (!scwin.Chk_Digit_Point_elw(val)) {
        return;
    }
    for (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        i = 0, k = 0; k < val.length; i++) {
        temp = "";
        for (j = 0; j < 4 && k < val.length;
            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************
            j++, k++) {
            int_unit = val.substr(val.length - (k + 1), 1);

            //han_unit_1 단위 추가
            if (int_unit > 0) {
                temp = han_unit_2[k % 4] + temp;
            }
            //han_unit_2 단위 추가
            if (int_unit == 1) {
                if (j == 0) temp = han_unit_1[int_unit] + temp;
            } else {
                temp = han_unit_1[int_unit] + temp;
            }
        }

        //han_unit_3 단위 추가
        if (temp != "") {
            if (val.length == 5 && temp == "일") {
                result = han_unit_3[i] + result;
            } else {
                result = temp + han_unit_3[i] + result;
            }
        }
    }
    if (result != "") result = "[" + result + "]";
    $("#" + id).text(result);
};



/*
