/**
 * @method
 * @name fc_chk_byte
 * @description desc
 * @param {string} aro_name desc
 * @param {string} ari_max desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fc_chk_byte = function(aro_name, ari_max) {
    var ls_str = aro_name.getValue();
    var li_str_len = ls_str.length;
    var li_max = ari_max;
    var i = 0;
    var li_byte = 0;
    var li_len = 0;
    var ls_one_char = "";
    var ls_str2 = "";
    for (i = 0; i < li_str_len; i++) {
        ls_one_char = ls_str.charAt(i);
        if (escape(ls_one_char).length > 4) {
            li_byte += 2;
        } else {
            li_byte++;
        }
        if (li_byte <= li_max) {
            li_len = i + 1;
        }
    }
    if (li_byte > li_max) {
        alert("문자열 최대 허용 길이를 초과 했습니다.");
        ls_str2 = ls_str.substr(0, li_len);
        $(aro_name).val(ls_str2);
        aro_name.focus();
    }
};
