/*
 * 표준코드신청내용구분코드로 상세조회 화면 분기 위한 구분값 리턴
 */
/**
 * @method
 * @name get_stdcd2stdTpCd
 * @description desc
 * @param {string} std_cd_appl_contn_tp_cd desc
 * @param {string} type2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.get_stdcd2stdTpCd = function(std_cd_appl_contn_tp_cd, type2) {
    //채권
    if (std_cd_appl_contn_tp_cd == "01") return "3";

    //주권
    if (std_cd_appl_contn_tp_cd == "02") return "2";

    //수익증권
    if (std_cd_appl_contn_tp_cd == "03") return "4";

    //신주인수권증권(WR)
    if (std_cd_appl_contn_tp_cd == "04") return "5";

    //신주인수권증서(R)
    if (std_cd_appl_contn_tp_cd == "05") return "55";

    //유가증권예탁증서(DR)
    if (std_cd_appl_contn_tp_cd == "06") return "8";

    //전자단기사채(77)/CP(7)
    if (std_cd_appl_contn_tp_cd == "07") {
        if (type2 == "CP") {
            return "7";
        } else {
            return "77";
        }
    }

    //스트립
    if (std_cd_appl_contn_tp_cd == "08") return "9";

    //양도성예금증서(CD)
    if (std_cd_appl_contn_tp_cd == "09") return "6";

    //주식워런트증권(ELW)
    if (std_cd_appl_contn_tp_cd == "10") return "11";

    //ELS/DLS
    if (std_cd_appl_contn_tp_cd == "11") return "10";

    //ETN
    if (std_cd_appl_contn_tp_cd == "12") return "14";

    //투자계약증권
    if (std_cd_appl_contn_tp_cd == "13") return "15";
};


