/*
 * 팝업사이즈 자동조절
 * 팝업페이지에서 onload후 호출
 */
/**
 * @method
 * @name popupAutoSize
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.popupAutoSize = function() {
    var thisX = parseInt(document.body.scrollWidth);
    var thisY = parseInt(document.body.scrollHeight);
    var maxThisX = screen.width - 50;
    var maxThisY = screen.height - 50;
    var marginY = 0;

    //브라우저별 높이 조절
    if (navigator.userAgent.indexOf("MSIE 6") > 0) //ie 6.x
        marginY = 45;

    else if (navigator.userAgent.indexOf("MSIE 7") > 0) //ie 7.x
        marginY = 75;

    else if (navigator.userAgent.indexOf("FireFox") > 0) //FireFox
        marginY = 50;

    else if (navigator.userAgent.indexOf("Opera") > 0) //Opera
        marginY = 30;

    else if (navigator.userAgent.indexOf("Netscape") > 0) //Netscape
        marginY = -2;
    if (thisX > maxThisX) {
        window.document.body.scroll = "yes";
        thisX = maxThisX;
    }
    if (thisY > maxThisY - marginY) {
        window.document.body.scroll = "yes";
        thisX += 19;
        thisY = maxThisY - marginY;
    }
    window.resizeTo(thisX + 10, thisY + marginY);
};
/**
 * @method
 * @name fn_delayKeyup
 * @description desc
 * @param {string} sPass desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_delayKeyup = function(sPass) {
    // 길이 9자  이상 체크 
    if (sPass.length == 0) {
        $("#PassOutput").html("");
        document.all.sendLevel.setValue("");
        return;
    } else if (sPass.length < 9) {
        $("#PassOutput").html("비밀번호는 9자 이상 입력하셔야 합니다.");
        document.all.sendLevel.setValue("");
        return;
    }
    $("#PassOutput").html("");
    var url = "/common/kisa.do?method=procCheckPassword";
    var params = "encryp_pw=" + sPass;
    $.post(url, params, function(obj) {
        if (obj == '') {
            //alert("KISA 검증 자료가 없습니다.");

        } else {
            var jsonData = $.parseJSON(obj);
            scwin.jsReturn(jsonData.sendResult, jsonData.sendLevel);
        }
    });
};




