/**
 * @method
 * @name jsReturn
 * @description desc
 * @param {string} bb desc
 * @param {string} level desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.jsReturn = function(bb, level) {
    while (bb.search("<0a>") > -1) {
        bb = bb.replace("<0a>", "<BR>");
    }
    $("#PassOutput").html(bb);
    document.all.sendLevel.setValue(level);
};


