/*
 * 항목 활성/비활성
 * sCompId : 항목ID
 * bEnable : true 활성
 *           false 비활성
 * bInitVal : 값 초기화 여부
 *
 */
/**
 * @method
 * @name fn_CompEnable
 * @description desc
 * @param {string} sCompId desc
 * @param {string} bEnable desc
 * @param {string} bInitVal desc
 * @param {string} bStyle desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CompEnable = function(sCompId, bEnable, bInitVal, bStyle) {
    if (bInitVal == undefined) {
        bInitVal = true;
    }
    if (bStyle == undefined) {
        bStyle = false;
    }
    if (bEnable) {
        $("#" + sCompId).removeAttr("disabled");
        $("#" + sCompId).attr("style", "background:");
    } else {
        $("#" + sCompId).attr("disabled", true);
        if (bInitVal) {
            $("#" + sCompId).val("");
        }
        if (bStyle) {
            $("#" + sCompId).attr("style", "background:#e2e2e2;");
        }
    }
};




