/*
 * 비밀번호 부분패킷암호화 패딩
 */
/**
 * @method
 * @name padString
 * @description desc
 * @param {string} source desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.padString = function(source) {
    var paddingChar = ' ';
    var size = 16;
    var x = source.length % size;
    var padLength = size - x;
    for (var i = 0; i < padLength; i++) source += paddingChar;
    return source;
};


