};


//주민번호 안내문구 깜빡임
/**
 * @method
 * @name fn_startBlink
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_startBlink = function() {
    if (document.all) {
        setInterval("fn_doBlink()", 1200);
    }
};
/**
 * @method
 * @name fn_doBlink
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_doBlink = function() {
    var blink = document.all.tags("BLINK");
    for (var i = 0; i < blink.length; i++) {
        blink[i].style.visibility = blink[i].style.visibility == "" ? "hidden" : "";
    }
};



//두날짜의 차이일수 구하기
/**
 * @method
 * @name fn_getPeriod
 * @description desc
 * @param {string} date1 desc
 * @param {string} date2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getPeriod = function(date1, date2) {
    var tmpYy1 = date1.substr(0, 4);
    var tmpMm1 = date1.substr(4, 2);
    var tmpDd1 = date1.substr(6, 2);
    var tmpYy2 = date2.substr(0, 4);
    var tmpMm2 = date2.substr(4, 2);
    var tmpDd2 = date2.substr(6, 2);
    var stDate = new Date(parseInt(tmpYy1), parseInt(tmpMm1) - 1, parseInt(tmpDd1));
    var endDate = new Date(parseInt(tmpYy2), parseInt(tmpMm2) - 1, parseInt(tmpDd2));
    var btMs = endDate.getTime() - stDate.getTime();
    var btDay = btMs / (1000 * 60 * 60 * 24);
    return btDay;
};



